<script setup lang="ts">
import {ref,onMounted,computed,watch} from 'vue'
import {api,ApiError,type Account} from './api'
const props=defineProps<{account:Account}>(),emit=defineEmits<{expired:[]}>()
type Row=Record<string,any>
const analyst=computed(()=>props.account.roles.includes('CENTER_ANALYST')),admin=computed(()=>props.account.roles.includes('CENTER_ADMIN'))
const error=ref(''),message=ref(''),busy=ref(false),sources=ref<Row[]>([]),source=ref<number>(),mappingId=ref<number>(),mappings=ref<Row[]>([]),batches=ref<Row[]>([]),rows=ref<Row[]>([]),selected=ref<number>(),file=ref<File>(),credentials=ref<Row[]>([]),token=ref(''),receipts=ref<Row[]>([])
const personId=ref<number>(),detail=ref<Row>(),reason=ref(''),manual=ref('MEDIUM'),ruleData=ref<Row>(),draft=ref<Row>(),preview=ref<Row>()
const thresholds=ref({medium:3,high:5}),keywords=ref<Row[]>([])
const fields=['personName','idCard','phone','eventTime','description','categoryId','disputeId'],labels=['姓名','身份证号','手机号','发生时间','问题描述','事件分类','纠纷类型']
const mappingName=ref(''),columns=ref<Record<string,string>>(Object.fromEntries(fields.map((f,i)=>[f,labels[i]]))),categoryAliases=ref(''),disputeAliases=ref(''),timeFormat=ref('ISO')
const credential=ref({name:'',departmentId:0,sourceId:0,specialReport:false})
const availableMappings=computed(()=>mappings.value.filter(m=>m.source_id===source.value))
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败';if(e instanceof ApiError&&e.status===401)emit('expired')}finally{busy.value=false}}
const post=<T,>(path:string,data:unknown)=>api<T>(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})
async function refresh(){sources.value=await api('/options/sources');if(analyst.value||props.account.roles.includes('DEPARTMENT_REPORTER')){mappings.value=await api('/batches/mappings');batches.value=await api('/batches')}if(analyst.value){ruleData.value=await api('/risk-governance/rules');receipts.value=await api('/batches/receipts')}if(admin.value)credentials.value=await api('/batches/credentials')}
async function openPerson(){detail.value=await api('/risk-governance/people/'+personId.value)}
async function adjust(){await post('/risk-governance/adjustments',{personId:personId.value,level:manual.value,fingerprint:detail.value!.fingerprint,reason:reason.value});await openPerson();message.value='人工调整已保存'}
async function exclude(item:Row){await post('/risk-governance/exclusions',{personId:personId.value,eventId:item.hit.eventId,ruleId:item.hit.ruleId,fingerprint:item.fingerprint,reason:reason.value});await openPerson();message.value='误命中已排除，风险已更新'}
function newDraft(){const active=ruleData.value!.active;thresholds.value={medium:active.medium,high:active.high};keywords.value=active.keywords.map((k:Row)=>({...k,terms:[...k.terms]}));draft.value=undefined;preview.value=undefined}
function editDraft(row:Row){const value=typeof row.payload==='string'?JSON.parse(row.payload):row.payload;thresholds.value={medium:value.medium,high:value.high};keywords.value=value.keywords;draft.value=row;preview.value=undefined}
watch([thresholds,keywords],()=>{preview.value=undefined},{deep:true})
async function saveDraft(){draft.value=await post('/risk-governance/rules',{id:draft.value?.id,version:draft.value?.version,rules:{...thresholds.value,keywords:keywords.value}});preview.value=undefined;await refresh();message.value='规则草稿已保存'}
async function doPreview(){preview.value=await post('/risk-governance/rules/'+draft.value!.id+'/preview',{})}
async function publish(){await post('/risk-governance/rules/'+draft.value!.id+'/publish',{version:draft.value!.version});draft.value=undefined;preview.value=undefined;await refresh();message.value='规则已发布，请刷新查看重算进度'}
async function upload(){if(!file.value||!source.value)throw Error('请选择来源和文件');const form=new FormData();form.append('file',file.value);form.append('sourceId',String(source.value));if(mappingId.value)form.append('mappingId',String(mappingId.value));const result=await api<Row>('/batches',{method:'POST',body:form});selected.value=result.id;await refresh();rows.value=await api('/batches/'+result.id);message.value='已接收，请刷新查看逐行结果'}
function aliases(value:string){return Object.fromEntries(value.split('\n').filter(Boolean).map(line=>{const i=line.indexOf('=');if(i<1)throw Error('别名格式为 原值=标准分类编号，每行一条');return [line.slice(0,i),line.slice(i+1)]}))}
async function saveMapping(){await post('/batches/mappings',{name:mappingName.value,sourceId:source.value,columns:columns.value,categories:aliases(categoryAliases.value),disputes:aliases(disputeAliases.value),timeFormat:timeFormat.value});await refresh();message.value='映射版本已保存'}
onMounted(()=>run(refresh))
</script>
<template><main class="content"><h1>规则与批量接入</h1><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><el-button :disabled="busy" @click="run(refresh)">刷新进度</el-button><el-tabs>
<el-tab-pane v-if="analyst||account.roles.includes('DEPARTMENT_REPORTER')" label="批量导入"><section class="event-card"><el-form label-position="top"><el-form-item label="可信数据来源"><el-select v-model="source" @change="mappingId=undefined"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="来源映射版本"><el-select v-model="mappingId" clearable placeholder="统一模板"><el-option v-for="m in availableMappings" :key="m.id" :value="m.id" :label="m.name+' · 版本 '+m.version"/></el-select></el-form-item><p v-if="source"><a :href="`/api/batches/template?sourceId=${source}&format=csv${mappingId?'&mappingId='+mappingId:''}`">下载 CSV 模板</a> · <a :href="`/api/batches/template?sourceId=${source}&format=xlsx${mappingId?'&mappingId='+mappingId:''}`">下载 Excel 模板</a></p><input type="file" accept=".csv,.xlsx" aria-label="导入文件" @change="file=($event.target as HTMLInputElement).files?.[0]"/><el-button :disabled="busy" @click="run(upload)">提交批量导入</el-button></el-form><p>最多5000行、5MB。错误行不影响其他行；下载失败行修正后重导。身份证和日期请使用文本单元格，日期格式默认为 ISO，例如 2026-10-18T12:00:00。</p><el-table :data="batches"><el-table-column prop="id" label="批次"/><el-table-column prop="filename" label="文件"/><el-table-column prop="total" label="总行数"/><el-table-column prop="pending" label="待处理"/><el-table-column prop="succeeded" label="成功"/><el-table-column prop="duplicates" label="重复"/><el-table-column prop="failed" label="失败"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="run(async()=>{selected=row.id;rows=await api('/batches/'+row.id)})">逐行结果</el-button><a :href="`/api/batches/${row.id}/failures`">失败文件</a> · <a :href="`/api/batches/${row.id}/original`">原文件</a></template></el-table-column></el-table><h3 v-if="selected">批次 #{{selected}}</h3><el-table :data="rows"><el-table-column prop="line_number" label="原始行号"/><el-table-column prop="state" label="结果"/><el-table-column prop="record_id" label="来源记录"/><el-table-column prop="error" label="失败原因"/></el-table></section></el-tab-pane>
<el-tab-pane v-if="analyst" label="误命中与人工调整"><section class="event-card"><el-input-number v-model="personId" :min="1" aria-label="风险人员编号"/><el-button :disabled="busy" @click="run(openPerson)">查看调整依据</el-button><template v-if="detail"><p>规则等级：{{detail.snapshot.ruleLevel}} · 有效人工调整：{{detail.snapshot.manualLevel||'无或已失效'}} · 最终等级：{{detail.snapshot.finalLevel}}</p><el-input v-model="reason" placeholder="排除或调整理由（必填）" aria-label="风险调整理由"/><el-select v-model="manual"><el-option v-for="l in ['LOW','MEDIUM','HIGH']" :key="l" :value="l" :label="l"/></el-select><el-button :disabled="busy" @click="run(adjust)">保存人工调整</el-button><article v-for="item in detail.hits" :key="item.hit.eventId+'-'+item.hit.ruleId"><h3>事件 #{{item.hit.eventId}} · {{item.hit.ruleName}}</h3><p v-for="e in item.hit.evidence" :key="e.recordId+'-'+e.field+'-'+e.term">来源 #{{e.recordId}} · {{e.field}}：{{e.text}}</p><el-button :disabled="busy" @click="run(()=>exclude(item))">排除此误命中</el-button></article><h3>调整历史（依据变化后自动失效）</h3><el-table :data="detail.adjustments"><el-table-column label="依据状态"><template #default="{row}">{{row.active?'依据未失效':'已失效'}}</template></el-table-column><el-table-column prop="level" label="调整等级"/><el-table-column prop="reason" label="原因"/><el-table-column prop="actor" label="操作者"/><el-table-column prop="created_at" label="时间"/></el-table><h3>计算历史</h3><el-table :data="detail.history"><el-table-column prop="created_at" label="计算时间"/><el-table-column label="历史依据"><template #default="{row}"><details><summary>查看历史规则和证据</summary><pre>{{JSON.stringify(typeof row.snapshot==='string'?JSON.parse(row.snapshot):row.snapshot,null,2)}}</pre></details></template></el-table-column></el-table><h3>排除历史</h3><el-table :data="detail.exclusions"><el-table-column label="状态"><template #default="{row}">{{row.active?'有效':'已失效'}}</template></el-table-column><el-table-column prop="event_id" label="事件"/><el-table-column prop="rule_id" label="规则"/><el-table-column prop="reason" label="原因"/></el-table></template></section></el-tab-pane>
<el-tab-pane v-if="analyst" label="规则发布"><section class="event-card"><p>特殊来源中风险保底固定生效。组合词在同一有效事件内同时出现才命中。</p><el-button :disabled="busy" @click="newDraft">新建规则草稿</el-button><el-form label-position="top"><el-form-item label="中风险起始次数"><el-input-number v-model="thresholds.medium" :min="1"/></el-form-item><el-form-item label="高风险起始次数"><el-input-number v-model="thresholds.high" :min="2"/></el-form-item><div v-for="k in keywords" :key="k.id"><el-input v-model="k.name" placeholder="规则名称"/><el-input :model-value="k.terms.join('、')" placeholder="组合关键词用顿号隔开" @update:model-value="k.terms=$event.split('、')"/><el-switch v-model="k.enabled" active-text="启用"/></div><el-button @click="keywords.push({id:Math.max(0,...keywords.map(k=>k.id))+1,name:'',terms:[''],enabled:true,version:1})">增加关键词规则</el-button><el-button :disabled="busy" @click="run(saveDraft)">保存规则草稿</el-button><el-button :disabled="busy||!draft" @click="run(doPreview)">预览影响</el-button><p v-if="preview">受影响 {{preview.affected}} 人 · 升级 {{preview.up}} 人 · 降级 {{preview.down}} 人</p><el-button :disabled="busy||!preview" @click="run(publish)">发布规则</el-button></el-form><el-table :data="ruleData?.releases"><el-table-column prop="id" label="规则版本"/><el-table-column prop="state" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.state==='DRAFT'" link @click="editDraft(row)">编辑草稿</el-button><el-button link @click="editDraft({...row,id:undefined,version:undefined})">复制配置</el-button></template></el-table-column></el-table><el-table :data="ruleData?.jobs"><el-table-column prop="id" label="重算任务"/><el-table-column prop="state" label="状态"/><el-table-column prop="completed" label="已完成"/><el-table-column prop="total" label="总人数"/><el-table-column prop="error" label="失败原因"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.state==='FAILED'" link @click="run(async()=>{await post('/risk-governance/jobs/'+row.id+'/retry',{});await refresh()})">重试</el-button></template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane v-if="analyst" label="来源映射"><section class="event-card"><p>先在批量导入页选择来源。保存同名映射会新增版本，旧批次保留原映射。</p><el-input v-model="mappingName" placeholder="映射名称"/><el-form label-position="top"><el-form-item v-for="(f,i) in fields" :key="f" :label="labels[i]+'对应列名'"><el-input v-model="columns[f]"/></el-form-item><el-form-item label="日期转换"><el-select v-model="timeFormat"><el-option v-for="f in ['ISO','yyyy/MM/dd HH:mm:ss','yyyy-MM-dd HH:mm:ss']" :key="f" :value="f"/></el-select></el-form-item><el-input v-model="categoryAliases" type="textarea" placeholder="事件分类别名：原值=标准分类编号，每行一条"/><el-input v-model="disputeAliases" type="textarea" placeholder="纠纷类型别名：原值=标准分类编号，每行一条"/><el-button :disabled="busy" @click="run(saveMapping)">保存映射新版本</el-button></el-form></section></el-tab-pane>
<el-tab-pane v-if="admin" label="外部接入凭据"><section class="event-card"><el-form label-position="top"><el-form-item label="凭据名称"><el-input v-model="credential.name"/></el-form-item><el-form-item label="绑定部门编号"><el-input-number v-model="credential.departmentId" :min="1"/></el-form-item><el-form-item label="绑定来源"><el-select v-model="credential.sourceId"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-switch v-model="credential.specialReport" active-text="允许特殊上报"/><el-button :disabled="busy" @click="run(async()=>{const c=await post<Row>('/batches/credentials',credential);token=c.token;await refresh()})">创建凭据</el-button></el-form><p v-if="token">仅本次显示，请保存：<code>{{token}}</code></p><el-table :data="credentials"><el-table-column prop="name" label="名称"/><el-table-column prop="department_id" label="部门"/><el-table-column prop="source_id" label="来源"/><el-table-column prop="enabled" label="启用"/><el-table-column label="操作"><template #default="{row}"><el-button :disabled="busy||!row.enabled" @click="run(async()=>{await api('/batches/credentials/'+row.id,{method:'DELETE'});await refresh()})">停用凭据</el-button></template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane v-if="analyst" label="外部接收结果"><section class="event-card"><el-table :data="receipts"><el-table-column prop="name" label="凭据"/><el-table-column prop="external_id" label="外部编号"/><el-table-column prop="record_id" label="来源记录"/><el-table-column prop="error" label="失败原因"/><el-table-column prop="created_at" label="接收时间"/></el-table></section></el-tab-pane>
</el-tabs></main></template>
